    },
    {
      "card_ids": ["C18"],
      "claim": "Lurtotecan, a larger fused heterocycle with poor oral absorption, has an absolute oral bioavailability of about 11%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Prucalopride, which shares a dihydrobenzofuran and piperidine but is a much smaller polar molecule, has an absolute oral bioavailability of 93.2%, providing a contradictory high-F reference with limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Risperidone, with a piperidine and fused heterocycles, has an absolute oral bioavailability of 66%, but its smaller size and different core limit transferability to the query.",
      "evidence_role": "contradictory"
    }
